    public RevenueReport(ReservationRepository repo, YearMonth month) {
        this.kept = repo.startingBetween(month.atDay(1), month.plusMonths(1).atDay(1)).stream()
                .filter(r -> r.retainedAmount().signum() > 0)
                .toList();
    }

