                        + r.status() + "," + r.retainedAmount().toPlainString())
                .toList();
    }

    @Override protected String total() {
        BigDecimal sum = kept.stream().map(Reservation::retainedAmount).reduce(Money.ZERO, BigDecimal::add);
        return "total," + sum.toPlainString();
    }
